-- Techniques (16)
insert into public.techniques (slug, name, names, description, difficulty) values
  ('tadka', 'Tempering (tadka)', '{"en": "Tempering (tadka)", "hi": "तड़का", "hi-Latn": "tadka"}'::jsonb, 'Whole spices bloomed in hot oil or ghee, then poured over or stirred into the dish. Right: cumin sizzles and darkens a shade within seconds, mustard seeds pop, curry leaves crackle. Too far: spices turn black and smell bitter; start again rather than use it.', 2),
  ('bhuna', 'Frying the masala (bhuna)', '{"en": "Frying the masala (bhuna)", "hi": "भूनना", "hi-Latn": "bhunna"}'::jsonb, 'Cooking onion, tomato and ground spices in oil, stirring, until the raw smell goes and the masala comes together. Right: the masala darkens, thickens into a paste, and oil shines at the edges and leaves the masala. If it sticks, splash in a little water and keep going.', 3),
  ('saute_onion', 'Browning onions', '{"en": "Browning onions", "hi": "प्याज़ भूनना", "hi-Latn": "pyaaz bhunna"}'::jsonb, 'Cooking sliced or chopped onion in oil to the colour the dish needs. Right: translucent and soft for light gravies, golden brown at the edges for most curries, deep brown for rich ones. Stir more often as they colour; they go from brown to burnt quickly.', 2),
  ('dum', 'Slow steaming under a seal (dum)', '{"en": "Slow steaming under a seal (dum)", "hi": "दम", "hi-Latn": "dum"}'::jsonb, 'Cooking covered on very low heat so the food finishes in its own steam. Right: lid sealed with dough or a heavy weight, gentle aroma escaping, no scorching smell from the base.', 4),
  ('pressure_cook', 'Pressure cooking', '{"en": "Pressure cooking", "hi": "प्रेशर कुकर", "hi-Latn": "cooker mein pakana"}'::jsonb, 'Cooking under pressure, counted in whistles. Right: count whistles at the heat the step says, then let the pressure drop on its own before opening. Never force the lid open while it is still hissing.', 1),
  ('simmer', 'Simmering', '{"en": "Simmering", "hi": "धीमी आंच पर पकाना", "hi-Latn": "dheemi aanch par pakana"}'::jsonb, 'Cooking a liquid just below the boil. Right: small lazy bubbles at the edges, not a rolling boil; stir now and then so the base does not catch.', 1),
  ('deep_fry', 'Deep frying', '{"en": "Deep frying", "hi": "तलना", "hi-Latn": "talna"}'::jsonb, 'Frying in enough oil for the food to float. Right: a drop of batter rises steadily to the top with bubbles; too cold and it sinks and soaks oil, too hot and it browns before cooking inside. Fry in small batches.', 3),
  ('shallow_fry', 'Shallow frying', '{"en": "Shallow frying", "hi": "कम तेल में तलना", "hi-Latn": "kam tel mein talna"}'::jsonb, 'Cooking in a thin layer of oil on a tawa or pan, turning once. Right: steady sizzle, golden crust that releases from the pan on its own.', 2),
  ('tawa_cook', 'Cooking on the tawa', '{"en": "Cooking on the tawa", "hi": "तवे पर सेंकना", "hi-Latn": "tawe par sekna"}'::jsonb, 'Cooking flatbreads and chillas on a hot griddle. Right: small bubbles rise within seconds, brown spots form underneath, edges lift easily.', 2),
  ('dry_roast', 'Dry roasting', '{"en": "Dry roasting", "hi": "सूखा भूनना", "hi-Latn": "sukha bhunna"}'::jsonb, 'Roasting spices, flour, sooji or poha in a dry pan. Right: a nutty aroma, an even shade darker, stirring constantly; take it off the heat a moment early because the pan keeps cooking.', 2),
  ('knead', 'Kneading dough', '{"en": "Kneading dough", "hi": "आटा गूंधना", "hi-Latn": "aata goondhna"}'::jsonb, 'Bringing flour and water together into a dough. Right: soft, smooth and not sticky; a finger pressed in leaves a dent that slowly fills back. Rest it covered.', 2),
  ('steam', 'Steaming', '{"en": "Steaming", "hi": "भाप में पकाना", "hi-Latn": "bhaap mein pakana"}'::jsonb, 'Cooking over boiling water, covered. Right: steady steam escaping; a toothpick or knife comes out clean when done.', 2),
  ('marinate', 'Marinating', '{"en": "Marinating", "hi": "मैरीनेट करना", "hi-Latn": "marinate karna"}'::jsonb, 'Coating meat, paneer or vegetables in curd, spices and acid before cooking. Right: evenly coated; raw meat marinates covered in the fridge, never on the counter.', 1),
  ('soak', 'Soaking', '{"en": "Soaking", "hi": "भिगोना", "hi-Latn": "bhigona"}'::jsonb, 'Soaking dals, beans, rice or sabudana in water before cooking. Right: grains swell and soften; discard the soaking water for rajma and other beans.', 1),
  ('batter', 'Making a batter', '{"en": "Making a batter", "hi": "घोल बनाना", "hi-Latn": "ghol banana"}'::jsonb, 'Whisking flour with water or curd into a smooth batter. Right: no lumps; coats the back of a spoon; thick enough to hold shape for pakoras, pourable for chillas.', 2),
  ('dhungar', 'Smoking with charcoal (dhungar)', '{"en": "Smoking with charcoal (dhungar)", "hi": "धुंगार", "hi-Latn": "dhungar"}'::jsonb, 'Smoking a dish with a hot coal and ghee in a small bowl, covered for a few minutes. Right: the coal glows red before use; cover at once; remove the coal before serving. Keep the kitchen ventilated.', 3)
on conflict (slug) do update set name = excluded.name, names = excluded.names,
  description = excluded.description, difficulty = excluded.difficulty;

