insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 1, 'Whisk the besan with turmeric, chilli powder, ajwain, salt and about 250 ml water into a smooth batter. Rest it for 10 minutes.', '{"en": "Whisk the besan with turmeric, chilli powder, ajwain, salt and about 250 ml water into a smooth batter. Rest it for 10 minutes."}'::jsonb, (select id from public.techniques where slug = 'batter'), 600, true, null, 'Smooth and pourable, like thin dosa batter. No lumps.', '{"en": "Smooth and pourable, like thin dosa batter. No lumps."}'::jsonb, '{"action": "Make the child''s chillas first", "age_group": "child", "before the green chilli goes into the batter": null}'::jsonb, null),
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 2, 'Stir in the finely chopped onion, tomato, green chilli and coriander.', '{"en": "Stir in the finely chopped onion, tomato, green chilli and coriander."}'::jsonb, null, 120, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 3, 'Heat the tawa on medium and grease it lightly. Pour a ladle of batter in the centre and spread it into a thin circle. Drizzle a little oil around the edge.', '{"en": "Heat the tawa on medium and grease it lightly. Pour a ladle of batter in the centre and spread it into a thin circle. Drizzle a little oil around the edge."}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 120, false, null, 'Small bubbles appear and the edges start to lift on their own.', '{"en": "Small bubbles appear and the edges start to lift on their own."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'besan-chilla'), 4, 'Flip and cook the other side, pressing gently. Repeat with the rest of the batter.', '{"en": "Flip and cook the other side, pressing gently. Repeat with the rest of the batter."}'::jsonb, (select id from public.techniques where slug = 'tawa_cook'), 900, false, null, 'Golden-brown spots on both sides and no raw batter in the middle.', '{"en": "Golden-brown spots on both sides and no raw batter in the middle."}'::jsonb, null, null)
