insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 1, 'Mix the chicken with the curd, half the ginger garlic paste, half the turmeric, half the chilli powder and a little salt. Cover and keep in the fridge.', '{"en": "Mix the chicken with the curd, half the ginger garlic paste, half the turmeric, half the chilli powder and a little salt. Cover and keep in the fridge."}'::jsonb, (select id from public.techniques where slug = 'marinate'), 1800, true, null, null, '{}'::jsonb, null, 'Wash your hands, the board and the knife with soap after handling raw chicken, and keep raw chicken away from food that will not be cooked. Marinate in the fridge, not on the counter.'),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 2, 'Heat the oil in a heavy kadai. Add the whole spices for 30 seconds, then the sliced onions. Cook, stirring more often as they colour.', '{"en": "Heat the oil in a heavy kadai. Add the whole spices for 30 seconds, then the sliced onions. Cook, stirring more often as they colour."}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 840, false, null, 'The onions are deep golden brown all over, not black at the edges.', '{"en": "The onions are deep golden brown all over, not black at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 3, 'Add the rest of the ginger garlic paste for a minute, then the chopped tomatoes, the remaining turmeric and chilli powder, coriander powder and salt. Cook, stirring.', '{"en": "Add the rest of the ginger garlic paste for a minute, then the chopped tomatoes, the remaining turmeric and chilli powder, coriander powder and salt. Cook, stirring."}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 480, false, null, 'The tomatoes melt into the masala and oil shines at the edges.', '{"en": "The tomatoes melt into the masala and oil shines at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 4, 'Add the chicken with all its marinade. Cook on high heat, stirring, so it sears and the masala coats every piece.', '{"en": "Add the chicken with all its marinade. Cook on high heat, stirring, so it sears and the masala coats every piece."}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 360, false, null, 'The chicken turns opaque on the outside.', '{"en": "The chicken turns opaque on the outside."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 5, 'Add 300 ml hot water, cover and simmer on low heat, stirring now and then.', '{"en": "Add 300 ml hot water, cover and simmer on low heat, stirring now and then."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 1500, true, null, 'The meat pulls away from the bone easily.', '{"en": "The meat pulls away from the bone easily."}'::jsonb, null, 'Chicken must be cooked through. Cut the thickest piece open to the bone; the meat should be white with no pink and the juices clear. If unsure, cook 5 more minutes and check again.'),
  ((select id from public.recipes where household_id is null and slug = 'chicken-curry'), 6, 'Add the garam masala and coriander leaves, cover and rest for 5 minutes before serving.', '{"en": "Add the garam masala and coriander leaves, cover and rest for 5 minutes before serving."}'::jsonb, null, 300, false, null, null, '{}'::jsonb, null, null)
