insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 1, 'Rinse the dal 2 to 3 times until the water runs almost clear, then soak in fresh water.', '{"en": "Rinse the dal 2 to 3 times until the water runs almost clear, then soak in fresh water."}'::jsonb, (select id from public.techniques where slug = 'soak'), 1200, true, null, 'Soaking is optional but makes the dal cook softer and faster.', '{"en": "Soaking is optional but makes the dal cook softer and faster."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 2, 'Drain and pressure-cook the dal with 600 ml water and the turmeric on medium heat.', '{"en": "Drain and pressure-cook the dal with 600 ml water and the turmeric on medium heat."}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 900, false, 4, 'Let the pressure drop by itself. The dal should mash completely when pressed with a spoon.', '{"en": "Let the pressure drop by itself. The dal should mash completely when pressed with a spoon."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 3, 'Whisk the dal smooth, add the salt and hot water until it pours like thick soup, and simmer.', '{"en": "Whisk the dal smooth, add the salt and hot water until it pours like thick soup, and simmer."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 4, 'For the tadka heat the ghee in a kadai. Add cumin, hing and garlic; when the garlic is golden add onion, ginger and green chilli and cook until the onion is light golden. Add the tomato and chilli powder and cook until soft.', '{"en": "For the tadka heat the ghee in a kadai. Add cumin, hing and garlic; when the garlic is golden add onion, ginger and green chilli and cook until the onion is light golden. Add the tomato and chilli powder and cook until soft."}'::jsonb, (select id from public.techniques where slug = 'tadka'), 420, false, null, 'Garlic should be golden, not brown. The tomato breaks down and the ghee shines at the edges.', '{"en": "Garlic should be golden, not brown. The tomato breaks down and the ghee shines at the edges."}'::jsonb, '{"action": "Take out the child''s dal before adding the chilli tadka; give it a little ghee and cumin only", "age_group": "child"}'::jsonb, null),
  ((select id from public.recipes where household_id is null and slug = 'dal-tadka'), 5, 'Pour the tadka into the dal, simmer 2 minutes, then add coriander leaves and lemon juice.', '{"en": "Pour the tadka into the dal, simmer 2 minutes, then add coriander leaves and lemon juice."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 120, false, null, null, '{}'::jsonb, null, null)
