insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 1, 'In a big bowl whisk the curd, 6 chammach besan, turmeric, red chilli powder and salt until completely smooth. Add 900 ml water and whisk again.', '{"en": "In a big bowl whisk the curd, 6 chammach besan, turmeric, red chilli powder and salt until completely smooth. Add 900 ml water and whisk again."}'::jsonb, (select id from public.techniques where slug = 'batter'), 180, false, null, 'No lumps at all, and as thin as buttermilk.', '{"en": "No lumps at all, and as thin as buttermilk."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 2, 'Pour into the kadai with the grated ginger. Bring to a boil on medium heat, stirring all the time.', '{"en": "Pour into the kadai with the grated ginger. Bring to a boil on medium heat, stirring all the time."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, false, null, 'Keep stirring until the first boil. If you stop, the curd can split.', '{"en": "Keep stirring until the first boil. If you stop, the curd can split."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 3, 'Lower the heat and let the kadhi simmer, stirring every few minutes.', '{"en": "Lower the heat and let the kadhi simmer, stirring every few minutes."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 1500, true, null, 'It thickens enough to coat the back of a spoon, and the raw besan smell is gone.', '{"en": "It thickens enough to coat the back of a spoon, and the raw besan smell is gone."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 4, 'Meanwhile make the pakora batter. Mix 2 katori besan with the sliced onion, green chilli, ajwain, a little salt and the soda, adding about 100 ml water slowly. Beat for 2 minutes.', '{"en": "Meanwhile make the pakora batter. Mix 2 katori besan with the sliced onion, green chilli, ajwain, a little salt and the soda, adding about 100 ml water slowly. Beat for 2 minutes."}'::jsonb, (select id from public.techniques where slug = 'batter'), 240, false, null, 'Thick enough to drop from a spoon in a blob. A drop of batter floats in a bowl of water.', '{"en": "Thick enough to drop from a spoon in a blob. A drop of batter floats in a bowl of water."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 5, 'Heat the oil in a second pan on medium. Drop small spoonfuls of batter and fry in batches until golden all over.', '{"en": "Heat the oil in a second pan on medium. Drop small spoonfuls of batter and fry in batches until golden all over."}'::jsonb, (select id from public.techniques where slug = 'deep_fry'), 720, false, null, 'The pakoras rise to the top and turn golden in about 4 minutes per batch.', '{"en": "The pakoras rise to the top and turn golden in about 4 minutes per batch."}'::jsonb, null, 'Keep children away from the hot oil. Slide the batter in close to the oil so it does not splash, and never let water drip into hot oil.'),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 6, 'Add the pakoras to the kadhi and simmer for 5 more minutes so they soak it up.', '{"en": "Add the pakoras to the kadhi and simmer for 5 more minutes so they soak it up."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 300, true, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kadhi-pakora'), 7, 'For the tadka, heat the ghee. Add cumin, methi dana, dry red chillies and hing. Turn off the heat, add Kashmiri chilli powder and pour over the kadhi at once.', '{"en": "For the tadka, heat the ghee. Add cumin, methi dana, dry red chillies and hing. Turn off the heat, add Kashmiri chilli powder and pour over the kadhi at once."}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'Cumin darkens one shade in a few seconds. Add the chilli powder off the heat so it turns red, not black.', '{"en": "Cumin darkens one shade in a few seconds. Add the chilli powder off the heat so it turns red, not black."}'::jsonb, '{"action": "Take out the child''s portion before pouring the chilli tadka", "age_group": "child"}'::jsonb, null)
