insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 1, 'Put the poha in a sieve and rinse under running water for a few seconds, 2 to 3 times. Do not soak. Sprinkle turmeric, salt and sugar, toss gently and leave for 5 minutes.', '{"en": "Put the poha in a sieve and rinse under running water for a few seconds, 2 to 3 times. Do not soak. Sprinkle turmeric, salt and sugar, toss gently and leave for 5 minutes."}'::jsonb, null, 300, true, null, 'A flake pressed between two fingers mashes easily but the poha is not mushy or wet.', '{"en": "A flake pressed between two fingers mashes easily but the poha is not mushy or wet."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 2, 'Heat the oil in a kadai and fry the peanuts until crunchy. Lift them out.', '{"en": "Heat the oil in a kadai and fry the peanuts until crunchy. Lift them out."}'::jsonb, (select id from public.techniques where slug = 'shallow_fry'), 180, false, null, 'The peanuts turn a shade darker and smell roasted.', '{"en": "The peanuts turn a shade darker and smell roasted."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 3, 'In the same oil add mustard seeds. When they pop, add curry leaves and green chilli, then the onion. Cook until soft.', '{"en": "In the same oil add mustard seeds. When they pop, add curry leaves and green chilli, then the onion. Cook until soft."}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 180, false, null, 'The onion turns translucent, not brown.', '{"en": "The onion turns translucent, not brown."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 4, 'Add the poha and toss gently on low heat. Cover and steam for 2 minutes.', '{"en": "Add the poha and toss gently on low heat. Cover and steam for 2 minutes."}'::jsonb, null, 120, true, null, 'The poha is hot all the way through and every flake is yellow.', '{"en": "The poha is hot all the way through and every flake is yellow."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'kanda-poha'), 5, 'Turn off the heat. Add the peanuts, lemon juice and coriander leaves and toss once.', '{"en": "Turn off the heat. Add the peanuts, lemon juice and coriander leaves and toss once."}'::jsonb, null, 60, false, null, null, '{}'::jsonb, null, null)
