  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 1, 'Cut the paneer into cubes and soak them in warm water so they stay soft. Grind the onion, ginger, garlic and green chilli to a paste, and the tomatoes to a separate puree.', '{"en": "Cut the paneer into cubes and soak them in warm water so they stay soft. Grind the onion, ginger, garlic and green chilli to a paste, and the tomatoes to a separate puree."}'::jsonb, null, 600, false, null, null, '{}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 2, 'Heat the oil in a kadai. Add cumin and the bay leaf, then the onion paste. Cook, stirring.', '{"en": "Heat the oil in a kadai. Add cumin and the bay leaf, then the onion paste. Cook, stirring."}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 600, false, null, 'The raw onion smell goes and the paste turns golden.', '{"en": "The raw onion smell goes and the paste turns golden."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 3, 'Add turmeric, Kashmiri chilli and coriander powder with a splash of water, stir for a minute, then add the tomato puree. Keep cooking and stirring.', '{"en": "Add turmeric, Kashmiri chilli and coriander powder with a splash of water, stir for a minute, then add the tomato puree. Keep cooking and stirring."}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 600, false, null, 'The masala thickens, darkens and the oil separates at the edges.', '{"en": "The masala thickens, darkens and the oil separates at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 4, 'Add the peas, salt and 300 ml water. Cover and simmer until the peas are soft.', '{"en": "Add the peas, salt and 300 ml water. Cover and simmer until the peas are soft."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 480, true, null, 'Fresh peas take about 8 minutes; frozen peas about 4.', '{"en": "Fresh peas take about 8 minutes; frozen peas about 4."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 5, 'Drain the paneer and add it to the gravy. Simmer for 3 minutes only.', '{"en": "Drain the paneer and add it to the gravy. Simmer for 3 minutes only."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 180, true, null, 'Do not boil the paneer for long or it turns rubbery.', '{"en": "Do not boil the paneer for long or it turns rubbery."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'matar-paneer'), 6, 'Add garam masala, crushed kasuri methi and cream. Stir, top with coriander leaves and serve.', '{"en": "Add garam masala, crushed kasuri methi and cream. Stir, top with coriander leaves and serve."}'::jsonb, null, 60, false, null, null, '{}'::jsonb, null, null)
