  ((select id from public.recipes where household_id is null and slug = 'moong-dal-khichdi'), 2, 'Heat the ghee in the pressure cooker. Add cumin, hing and grated ginger and stir for 30 seconds.', '{"en": "Heat the ghee in the pressure cooker. Add cumin, hing and grated ginger and stir for 30 seconds."}'::jsonb, (select id from public.techniques where slug = 'tadka'), 60, false, null, 'The cumin sizzles and smells toasty.', '{"en": "The cumin sizzles and smells toasty."}'::jsonb, null, null),
