  ((select id from public.recipes where household_id is null and slug = 'moong-dal-khichdi'), 4, 'Stir and mash lightly. Add hot water if it is too thick, and serve with a little ghee on top.', '{"en": "Stir and mash lightly. Add hot water if it is too thick, and serve with a little ghee on top."}'::jsonb, null, 120, false, null, 'It should flow slowly from the spoon, like a thick porridge. It thickens as it stands.', '{"en": "It should flow slowly from the spoon, like a thick porridge. It thickens as it stands."}'::jsonb, null, null)
