insert into public.recipe_steps (recipe_id, step_no, instruction, instructions, technique_id, duration_sec,
  timer_required, whistles, sensory_cue, sensory_cues, member_branch, safety_note) values
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 1, 'Rinse the rajma and soak in plenty of water overnight, at least 8 hours.', '{"en": "Rinse the rajma and soak in plenty of water overnight, at least 8 hours."}'::jsonb, (select id from public.techniques where slug = 'soak'), 28800, false, null, 'The beans double in size and the skins are smooth.', '{"en": "The beans double in size and the skins are smooth."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 2, 'Drain and throw away the soaking water. Pressure-cook the rajma with 750 ml fresh water and the salt.', '{"en": "Drain and throw away the soaking water. Pressure-cook the rajma with 750 ml fresh water and the salt."}'::jsonb, (select id from public.techniques where slug = 'pressure_cook'), 1800, false, 8, 'Let the pressure drop by itself. A bean should mash easily between two fingers and be creamy inside.', '{"en": "Let the pressure drop by itself. A bean should mash easily between two fingers and be creamy inside."}'::jsonb, null, 'Raw or undercooked kidney beans are poisonous. Always soak, throw away the soaking water, and cook until every bean is completely soft. If any bean is still firm, cook for more whistles. Never cook rajma from raw in a slow cooker.'),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 3, 'Heat the oil in a kadai. Add cumin and the bay leaf, then the finely chopped onion and cook until deep golden.', '{"en": "Heat the oil in a kadai. Add cumin and the bay leaf, then the finely chopped onion and cook until deep golden."}'::jsonb, (select id from public.techniques where slug = 'saute_onion'), 600, false, null, 'The onion is evenly golden brown at the edges.', '{"en": "The onion is evenly golden brown at the edges."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 4, 'Add grated ginger, garlic and green chilli for a minute, then the tomato puree, turmeric, Kashmiri chilli and coriander powder. Cook, stirring.', '{"en": "Add grated ginger, garlic and green chilli for a minute, then the tomato puree, turmeric, Kashmiri chilli and coriander powder. Cook, stirring."}'::jsonb, (select id from public.techniques where slug = 'bhuna'), 600, false, null, 'The masala is thick and dark and the oil leaves the sides.', '{"en": "The masala is thick and dark and the oil leaves the sides."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 5, 'Add the rajma with its cooking water. Mash a few beans against the side of the pan for body and simmer on low heat.', '{"en": "Add the rajma with its cooking water. Mash a few beans against the side of the pan for body and simmer on low heat."}'::jsonb, (select id from public.techniques where slug = 'simmer'), 900, true, null, 'The gravy thickens and coats the beans.', '{"en": "The gravy thickens and coats the beans."}'::jsonb, null, null),
  ((select id from public.recipes where household_id is null and slug = 'rajma'), 6, 'Add garam masala and coriander leaves and serve with rice.', '{"en": "Add garam masala and coriander leaves and serve with rice."}'::jsonb, null, 60, false, null, null, '{}'::jsonb, null, null)
